//! Design tokens at run time (PRD R102.1, ADR-0036 §3): the table and the GTK
//! stylesheet generated by `build.rs` from `tokens.toml`. Rust code that needs a
//! color (Pango markup, a WebView background, the Terminal's default colors)
//! reads it here, never writes one.
include!(concat!(env!("OUT_DIR"), "/tokens.rs"));

/// `@define-color` per token: the light half, then the dark half.
pub const CSS: &str = include_str!(concat!(env!("OUT_DIR"), "/tokens.css"));

/// `(light, dark)` halves of [`CSS`].
pub fn css_halves() -> (&'static str, &'static str) {
    CSS.split_once("/* theme: dark */").unwrap_or((CSS, ""))
}

/// A token's `#rrggbb[aa]` in one theme. Panics on an unknown name: token
/// names are fixed at build time and covered by the unit tests.
pub fn get(name: &str, dark: bool) -> &'static str {
    let list = if dark { DARK } else { LIGHT };
    list.iter()
        .find(|(k, _)| *k == name)
        .map(|(_, v)| *v)
        .unwrap_or_else(|| panic!("unknown design token '{name}'"))
}

/// Whether the style is dark now.
pub fn dark() -> bool {
    libadwaita::StyleManager::default().is_dark()
}

/// [`rgb`] in the current style.
pub fn rgb_now(name: &str) -> &'static str {
    rgb(name, dark())
}

/// `#rrggbb` of a token without its alpha (Pango markup takes the alpha apart).
pub fn rgb(name: &str, dark: bool) -> &'static str {
    &get(name, dark)[..7]
}
